const http = require('http');
const url = require('url');
const crypto = require('crypto');

// Multi-tenant proxy with admin dashboard
const tenants = new Map();
const sessions = new Map();

class TenantContext {
  constructor(id, config) {
    this.id = id;
    this.config = config;
    this.requestLog = [];
  }

  logRequest(req) {
    this.requestLog.push({
      timestamp: Date.now(),
      method: req.method,
      path: req.url,
      headers: Object.assign({}, req.headers)
    });
    if (this.requestLog.length > 100) this.requestLog.shift();
  }
}

function initTenants() {
  tenants.set('acme', new TenantContext('acme', { upstream: 'http://acme.internal:8080', theme: 'blue' }));
  tenants.set('globex', new TenantContext('globex', { upstream: 'http://globex.internal:8080', theme: 'green' }));
}

function authenticate(req) {
  const cookies = parseCookies(req.headers.cookie || '');
  const sessionId = cookies['proxy_session'];
  if (sessionId && sessions.has(sessionId)) {
    return sessions.get(sessionId);
  }
  return null;
}

function parseCookies(cookieStr) {
  const cookies = {};
  cookieStr.split(';').forEach(pair => {
    const [key, ...vals] = pair.trim().split('=');
    if (key) cookies[key.trim()] = vals.join('=').trim();
  });
  return cookies;
}

function encodeTenantId(tenantId) {
  // Encode for safe embedding - allows alphanumeric and hyphens
  return tenantId.replace(/[^a-zA-Z0-9\-]/g, '');
}

function buildContextHeader(tenant, nonce) {
  // Build a serialized context for the downstream rendering layer
  const ctx = {
    tenant_id: tenant.id,
    theme: tenant.config.theme,
    nonce: nonce
  };
  return Buffer.from(JSON.stringify(ctx)).toString('base64');
}

function renderDashboard(tenant, session) {
  const nonce = crypto.randomBytes(16).toString('hex');
  const contextHeader = buildContextHeader(tenant, nonce);

  // The dashboard renders recent request logs for the tenant
  const logEntries = tenant.requestLog.slice(-20).map(entry => {
    // Serialize log entry for client-side rendering
    return JSON.stringify({
      time: entry.timestamp,
      method: entry.method,
      path: entry.path,
      host: entry.headers.host || 'unknown'
    });
  });

  // Build the HTML dashboard with CSP
  const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'">
  <title>Proxy Dashboard - ${encodeTenantId(tenant.id)}</title>
  <style nonce="${nonce}">body { font-family: sans-serif; } .log-entry { padding: 4px; border-bottom: 1px solid #eee; }</style>
</head>
<body>
  <h1>Dashboard: ${encodeTenantId(tenant.id)}</h1>
  <div id="log-container"></div>
  <script nonce="${nonce}">
    (function() {
      var entries = [${logEntries.join(',')}];
      var container = document.getElementById('log-container');
      entries.forEach(function(entry) {
        var div = document.createElement('div');
        div.className = 'log-entry';
        div.innerHTML = '<strong>' + entry.method + '</strong> ' + entry.path + ' <em>(' + entry.host + ')</em>';
        container.appendChild(div);
      });
    })();
  </script>
</body>
</html>`;
  return { html, nonce, contextHeader };
}

function handleProxy(req, res, tenant) {
  tenant.logRequest(req);
  // Forward to upstream (simplified)
  res.writeHead(200, { 'Content-Type': 'text/plain' });
  res.end(`Proxied to ${tenant.config.upstream}`);
}

function handleDashboardRequest(req, res, session) {
  const tenant = tenants.get(session.tenantId);
  if (!tenant) {
    res.writeHead(404);
    res.end('Tenant not found');
    return;
  }
  const { html, nonce, contextHeader } = renderDashboard(tenant, session);
  res.writeHead(200, {
    'Content-Type': 'text/html; charset=utf-8',
    'X-Proxy-Context': contextHeader,
    'X-Content-Type-Options': 'nosniff',
    'X-Frame-Options': 'DENY'
  });
  res.end(html);
}

function resolveTenant(req) {
  // Tenant resolution via Host header subdomain
  const host = req.headers.host || '';
  const subdomain = host.split('.')[0];
  return tenants.get(subdomain) || null;
}

const server = http.createServer((req, res) => {
  const parsed = url.parse(req.url, true);

  if (parsed.pathname === '/_proxy/dashboard') {
    const session = authenticate(req);
    if (!session) {
      res.writeHead(401);
      res.end('Unauthorized');
      return;
    }
    handleDashboardRequest(req, res, session);
    return;
  }

  if (parsed.pathname === '/_proxy/login') {
    // Simplified login for demo
    const tenantId = parsed.query.tenant;
    if (tenantId && tenants.has(tenantId)) {
      const sessionId = crypto.randomBytes(32).toString('hex');
      sessions.set(sessionId, { tenantId: tenantId, created: Date.now() });
      res.writeHead(302, {
        'Set-Cookie': `proxy_session=${sessionId}; HttpOnly; SameSite=Strict; Path=/`,
        'Location': '/_proxy/dashboard'
      });
      res.end();
      return;
    }
    res.writeHead(400);
    res.end('Invalid tenant');
    return;
  }

  // Normal proxy path
  const tenant = resolveTenant(req);
  if (!tenant) {
    res.writeHead(404);
    res.end('Unknown tenant');
    return;
  }
  handleProxy(req, res, tenant);
});

initTenants();
server.listen(3000, () => console.log('Multi-tenant proxy on :3000'));
